-- Uçuş Kontrol & Kurulum (T3 7.4, 12, 13) altyazıları: ojglF4fv1PQ, 8f-im0KARBg, PEz0mP5WJPM.
-- Kaynak: oynatıcının otomatik Türkçe altyazısı (hızlı oynatılıp toplandı; ASR hataları olabilir).
-- Her sorunun kaynak video id ve altyazıdan alıntısı aşağıdaki yorumlardadır.
-- Uçuş Kontrol & Kurulum orta/zor quizlerine EKLENİR. Idempotent: aynı soru metni varsa atlanır.

begin;

-- ojglF4fv1PQ kaynak: dengenin sağlanması: jiroskop ve ivmeölçer sensörleri ile İHA'nın eğimini ve hareketlerini kontrol eder... motorların yönetilmesi... otomatik stabilizasyon... geri dönüş ve otonom uçuş: GPS ve barometre... telemetri ve haberleşme.
-- 8f-im0KARBg kaynak: Ayarlar sekmesine geldiğimiz vakit buradaki ayarları sırasıyla yapmamız gerekiyor. Herhangi bir atlama yapmadan en baştan sonuna kadar ayarlamaları yapmamız gerekiyor. Bu sıralamaya muhakkak uymalıyız.
-- 8f-im0KARBg kaynak: Sanal ufuk ayarlaması yatış, yunuslama ve sapma açılarının doğru çalışmasını etkiler... aracı düz bir zemine bıraktım, sanal ufuk sıfırlama butonuna tıklıyorum, yunuslama ve yatış açıları 0 derece.
-- PEz0mP5WJPM kaynak: teste başlamadan öncesinde muhakkak bir uçuş, kayıt ve kontrol listesi oluşturmamız gerekiyor. Uçuş öncesinde ne yapacaklarımız, uçuş sırasında neler yapacağımız ve uçuş sonrasında neleri değerlendireceğimiz muhakkak bulunmalı.
do $q$
declare v_quiz uuid; v_q uuid; v_sira int; r jsonb; o jsonb; j int;
begin
  select z.id into v_quiz from public.quizzes z join public.modules m on m.id = z.module_id
   where m.ad = 'Uçuş Kontrol & Kurulum' and z.zorluk = 'orta' limit 1;
  if v_quiz is null then raise notice 'Quiz yok, atlanıyor: Uçuş Kontrol & Kurulum orta'; return; end if;
  select coalesce(max(sira), 0) into v_sira from public.questions where quiz_id = v_quiz;
  for r in select * from jsonb_array_elements($json$[{"m":"Videoya göre uçuş kontrol kartının görevleri hangileridir? (birden çok)","a":"Ayrıca otomatik stabilizasyon ve telemetri/haberleşme görevleri vardır.","o":[["Jiroskop ve ivmeölçerle dengeyi sağlamak",true],["ESC'ye sinyal göndererek motorları yönetmek",true],["GPS ve barometreyle otonom uçuş ve geri dönüş yapmak",true],["Bataryayı şarj etmek",false]]},{"m":"Videodaki arayüzde ayarlar nasıl yapılmalıdır?","a":"Bağlanırken uygun port ve baud hızı seçilir (videoda COM5, 57.600).","o":[["Sırasıyla, hiçbirini atlamadan en baştan sona; sıralamaya uyularak",true],["İstenen sırayla, istenmeyenler atlanarak",false],["Yalnızca güvenlik ayarları yapılır",false],["Ayarlara gerek yoktur",false]]},{"m":"Sanal ufuk ayarı nasıl yapılır?","a":"Sıfırlamadan önce veri panelinde sapma açısı görülebilir; örnekte yunuslama 2° idi.","o":[["Araç düz bir zemine bırakılıp sanal ufuk sıfırlama butonuna basılır; yatış ve yunuslama açıları 0° olur",true],["Araç havaya atılıp sıfırlanır",false],["Motorlar tam güçte çalıştırılır",false],["GPS verisi sıfırlanır",false]]},{"m":"Videoya göre test uçuşundan önce ne hazırlanmalıdır ve neleri içermelidir?","a":"Liste ileride uçuş amaçlarına, başarı ve hata türlerine geri dönüp bakmayı sağlar.","o":[["Uçuş, kayıt ve kontrol listesi: uçuş öncesi yapılacaklar, uçuş sırasında yapılacaklar ve uçuş sonrası değerlendirmeler",true],["Yalnızca bataryanın şarj listesi",false],["Yalnızca uçuş sonrası fotoğraf listesi",false],["Liste gerekmez, deneyim yeterlidir",false]]}]$json$::jsonb) loop
    if exists (select 1 from public.questions where quiz_id = v_quiz and metin = r->>'m') then continue; end if;
    v_sira := v_sira + 1;
    insert into public.questions (quiz_id, metin, sira, aciklama)
      values (v_quiz, r->>'m', v_sira, r->>'a') returning id into v_q;
    j := 0;
    for o in select * from jsonb_array_elements(r->'o') loop
      j := j + 1;
      insert into public.question_options (question_id, metin, dogru, sira)
        values (v_q, o->>0, (o->>1)::boolean, j);
    end loop;
  end loop;
end $q$;

-- ojglF4fv1PQ kaynak: Pixhawk açık kaynak kodlu bir uçuş kontrol kartıdır... MAVLink adı verilen iki yönlü bir haberleşme protokolü kullanılır. DroneKit MAVLink protokolü ile çalışan açık kaynak kodlu bir yazılım geliştirme kitidir; Python dilinde programlama yaparak Pixhawk tabanlı sistemlerle iletişim kurmayı mümkün kılar. Mission Planner Pixhawk tabanlı sistemler için kullanılan yaygın bir kullanıcı arayüz yazılımıdır.
-- ojglF4fv1PQ kaynak: Alaca uçuş kontrol kartı Gaziantep Teknopark'ta faaliyet gösteren firma tarafından geliştirilen yerli kartlardandır; özellikle sabit kanatlı İHA'lar için geliştirilmiştir... manuel, yarı otonom, tam otonom ve geri dönüş modları... aktif takip modu... eğitim modu... ALC Link açık kaynak kütüphane.
-- ojglF4fv1PQ kaynak: Alaca BNO055 9 dereceli serbestlikte hareketleri algılayabilen IMU sensörüne sahiptir. MS5611 yüksek hassasiyetli basınç sensörü. 6 adet PWM çıkışı motor kontrolü ve hız ayarı için.
-- 8f-im0KARBg kaynak: Araç türümüz sabit kanat, bir motorlu, konvansiyonel kuyruk yapısı. Varsayılan ayarlarla kaydedince servo ve kanal atamaları otomatik yapılır... birinci pin yatış servosu, ikinci pin yunuslama servosu, üçüncü pin motor (ESC), dördüncü pin sapma servosu.
-- 8f-im0KARBg kaynak: Sahaya çıkmadan önce mutlaka uçağımıza pervane takmamalıyız. Kartın üzerindeki bağlantıları takıp çıkartırken kartın üzerinde herhangi bir güç bulunmamalı.
-- 8f-im0KARBg kaynak: Kontrol ayarı yatış, yunuslama ve sapma eksenlerindeki kontrolcünün katsayılarını ayarlayabildiğim bir sekme... ilk defa uçuş yapanlar bu katsayıları varsayılan ayarlarda kullanabilirler. 35 derecelik yatış açısı, 25 derecelik yunuslama açısı ve 4 oranlık sapma etki oranı yeterli.
-- 8f-im0KARBg kaynak: mod değişikliğini yapacağım kanalımı seçiyorum, kanal 5. Manuel modu uçuş dışında kullanacağız; denge uçuşu gerçekleştireceğiz.
-- 8f-im0KARBg kaynak: Servo ayarlarına başlarken ilk etapta ESC kalibrasyonunu yapmamız gerekiyor... aracın bütün güç bağlantılarını kapatıp kumandamı açıyorum, batarya bağlantısını gerçekleştiriyorum, otomatik olarak ESC kalibrasyon moduna girecek, sesi dinliyorum.
-- 8f-im0KARBg kaynak: denge modunu alarak aracın doğru tepkileri verip vermediğini kontrol edeceğim... sola doğru yatırdığım vakitte kanatçıklar otomatik olarak kontrol ediliyor, sol kanatçığım yukarı kalkarak tekrardan denge moduna geri dönmeye çalışıyor. Eğer yönlerden biri yanlış olsaydı buradan ters etki yaparak ayarlayabilecektim.
-- 8f-im0KARBg kaynak: güvenlik ayarlarında motor açma kapatma: kapatmak için full gaz aşağı ve full sol rudder vereceğim... tam tersi yaparak full gaz aşağı ve tam sağ rudder yaparak uçağımı aktif hale getiriyorum.
-- 8f-im0KARBg kaynak: Genel bağlantı güvenlik ayarları... düşük batarya veya telemetre bağlantısı kopması durumunda aracınızın ne yapması gerektiğini belirliyorsunuz... motor kapat seçeneğini aktif edebilirim veya otonom eve dönüş modlarını.
-- PEz0mP5WJPM kaynak: Bu aşamada kesinlikle pervaneyi takmıyorum. Pervaneyi uçuşa gitmeden hemen önce takacağım. Uçağımı açmadan önce öncelikle mekanik sistemlerin kontrolünü yapacağım: motor bağlantı aparatı, kanat bağlantısı, servo motorlar, yekeler, stoper bağlantıları, kontrol yüzeyleri, batarya, uçuş kontrol kartı, alıcı ve telemetre, GPS sabitliği.
-- PEz0mP5WJPM kaynak: Şu anda motorum kapalı... güvenlik durumunu aktif etmem gerekiyor. Full gaz aşağı ve tam sağ rudder yapıyorum. Artık uçağım aktif durumda.
-- PEz0mP5WJPM kaynak: tam gaz testi... hem uçuş öncesinde hem de uçuşa başlamadan hemen önce yapmamız gerekiyor. Amaç: batarya seviyesini ölçmüş olsak bile batarya seviyesi düşükse motor full gazda tam performansıyla çalışamayacaktır. Bunu uçuş öncesinde fark ederek uçuşu iptal edebiliriz.
-- PEz0mP5WJPM kaynak: Şimdi uçuşumuzun amacını yazmamız gerekiyor. Çünkü ilerleyen zamanlarda geriye dönüp bakabiliriz: hangi amaçlar için uçuş yapmışız, kaçında başarılı olmuşuz, kaçında hata yapmışız, hatalarımızın türü ne, nasıl çözümler bulmuşuz.
-- PEz0mP5WJPM kaynak: rüzgara doğru kalkış yapılır. Aynı zamanda rüzgara doğru da iniş yapılır... kalkışı elle atarak başlatacak... ilk olarak denge uçuşu yapıyoruz çünkü aracı tanımamız gerekiyor. Daha sonrasında otonom uçuş yapacağız.
-- PEz0mP5WJPM kaynak: bıraktığım zaman kendisi burun aşağı doğru yapıyor. Buradan kumandamdan trim yapacağım. Bir miktar burun yukarı trim yaptım. Artık uçağımın düzgün uçtuğundan eminim.
-- PEz0mP5WJPM kaynak: otonom uçuş öncesinde mutlaka pusula kalibrasyonu yapmamız gerekiyor. Pusula kalibrasyonu yaparken aracımızı her yönde döndüreceğiz. Eğer pusula kalibrasyonu tam olarak yapılamazsa aracımız otonomdayken yönünü bulamayacaktır.
do $q$
declare v_quiz uuid; v_q uuid; v_sira int; r jsonb; o jsonb; j int;
begin
  select z.id into v_quiz from public.quizzes z join public.modules m on m.id = z.module_id
   where m.ad = 'Uçuş Kontrol & Kurulum' and z.zorluk = 'zor' limit 1;
  if v_quiz is null then raise notice 'Quiz yok, atlanıyor: Uçuş Kontrol & Kurulum zor'; return; end if;
  select coalesce(max(sira), 0) into v_sira from public.questions where quiz_id = v_quiz;
  for r in select * from jsonb_array_elements($json$[{"m":"Videoda Pixhawk, MAVLink, DroneKit ve Mission Planner arasındaki ilişki nasıl anlatılır?","a":"Pixhawk özellikle quadcopter gibi döner kanatlı araçlarda ve endüstriyel projelerde yaygındır.","o":[["Pixhawk MAVLink adlı iki yönlü protokolü kullanır; DroneKit Python ile bu protokol üzerinden görev yazmayı, Mission Planner ise ayar, görev planlama ve analizi sağlar",true],["Pixhawk kapalı kaynaklıdır ve yalnızca Windows'ta çalışır",false],["MAVLink yalnızca kamera protokolüdür",false],["DroneKit C++ ile yazılmıştır ve MAVLink kullanmaz",false]]},{"m":"Videodaki yerli Alaca uçuş kontrol kartı için hangisi doğrudur?","a":"Kart hava, kara ve deniz platformlarına uygun hazır arayüz şablonları sunar.","o":[["Özellikle sabit kanatlı İHA'lar için geliştirilmiş yerli kartlardandır; manuel, yarı otonom, tam otonom, geri dönüş, aktif takip ve eğitim modlarına sahiptir; açık kaynak ALC Link kütüphanesi vardır",true],["Yalnızca çok rotorlu araçlar için, yurt dışı üretimdir",false],["Hiçbir uçuş modu sunmaz",false],["Yalnızca su altı araçlarında kullanılır",false]]},{"m":"Alaca kartın teknik özellikleri videoda nasıl sayılır?","a":"Kartın 1 SPI, 1 I2C ve 2 UART portu vardır; PWM çoğaltıcı, RGB LED modülü gibi modüller eklenebilir.","o":[["BNO055 (9 serbestlik dereceli IMU), MS5611 basınç sensörü ve 6 adet PWM çıkışı",true],["MPU6050 IMU, GPS yerleşik ve 12 PWM çıkışı",false],["Yalnızca barometre, PWM çıkışı yok",false],["Kamera ve lazer mesafe sensörü yerleşik",false]]},{"m":"Videoda araç tercihi varsayılanla kaydedildikten sonra kart pinlerine hangi bileşenler bağlanır?","a":"Arayüz, ekrandaki tabloda hangi pinin hangi servoya bağlanacağını gösterir.","o":[["1. pin yatış servosu, 2. pin yunuslama servosu, 3. pin motor (ESC), 4. pin sapma servosu",true],["1. pin motor, 2. pin GPS, 3. pin batarya, 4. pin kamera",false],["Hepsi aynı pine bağlanır",false],["Pin atamasını kullanıcı kafasına göre yapar",false]]},{"m":"Videodaki kurulum sırasında hangi güvenlik uyarıları verilir?","a":"Ayarlamalar yapılırken motorun beklenmedik şekilde dönmesi riskine karşı alınır.","o":[["Ayarlar yapılırken pervane takılı olmamalı; kart bağlantıları takılıp çıkarılırken kartta güç bulunmamalı",true],["Bağlantılar güç açıkken değiştirilmelidir",false],["Pervane takılı olmalıdır",false],["Güvenlik uyarısı yoktur",false]]},{"m":"İlk uçuş için kontrol ayarında videoda ne önerilir?","a":"Kontrol ayarı ayrıca otonom kontrol sınırlarını belirlemeye yarar.","o":[["Varsayılan katsayılar kullanılır; örnekte 35° yatış, 25° yunuslama ve 4 sapma etki oranı yeterlidir",true],["Katsayılar sıfırlanır",false],["Yatış açısı 90° yapılır",false],["Kontrol ayarı yapılmaz",false]]},{"m":"İlk uçuş için çalışma modları ayarında videoda hangi modlar atanır?","a":"Bu sekmede otonom eve dönme, aktif takip ve eğitim modu ayarları da yapılabilir.","o":[["Mod kanalı olarak kanal 5 seçilir; manuel (uçuş dışında) ve denge (uçuş için) modları atanır",true],["Yalnızca tam otonom mod atanır",false],["Kanal 1 mod kanalı olur, tüm modlar otonom olur",false],["Mod ataması yapılmaz",false]]},{"m":"Videodaki ESC kalibrasyonu nasıl yapılır?","a":"Kalibrasyon sesler tamamlanınca bitmiş olur.","o":[["Servo ayarlarında ESC kalibrasyonu kullanıma alınıp kaydedilir; güç kapatılır, kumanda açılır ve batarya bağlanınca araç otomatik kalibrasyon moduna girer, sesler dinlenir",true],["Pervane takılıyken tam gazla uçulur",false],["Yalnızca arayüzde Calibrate ESC'ye basılır",false],["ESC kalibrasyonu gerekmez",false]]},{"m":"Servo yönleri videoda nasıl doğrulanır?","a":"Yatış, yunuslama ve sapma eksenleri tek tek denenir.","o":[["Denge modunda araç elle yatırılıp eğilir; kanatçık/irtifa/yön dümeni aracı dengeye döndürecek yönde hareket etmelidir, yanlışsa servo yönü ters çevrilir",true],["Pervane takılıp havada denenir",false],["Yalnızca kumandadan komut verilir",false],["Yön kontrolü gerekmez",false]]},{"m":"Videodaki güvenlik ayarında motorlar kumandadan nasıl kapatılıp açılır?","a":"Bu ayar uçuş öncesi ve sonrasında motorların güvenli şekilde pasif tutulmasını sağlar.","o":[["Gaz en aşağı + tam sol rudder ile kapanır; gaz en aşağı + tam sağ rudder ile aktif olur",true],["Gaz en yukarı + tam sol rudder ile kapanır",false],["Yalnızca arayüzdeki butonla kapatılır",false],["Hiçbir şekilde kapatılamaz",false]]},{"m":"Genel bağlantı güvenlik ayarı ne işe yarar?","a":"Videoda ilk uçuşta kullanım dışı bırakılmıştır.","o":[["Düşük batarya veya telemetri bağlantısı kopması durumunda aracın ne yapacağını belirler (ör. motor kapat veya otonom eve dönüş)",true],["Pil kapasitesini artırır",false],["Kumanda kanal sayısını belirler",false],["GPS yerleşimini değiştirir",false]]},{"m":"Videodaki uçuş öncesi kontrollerde pervane ve mekanik kontroller nasıl yapılır?","a":"Aviyonik kontrollerde batarya seviyesi, uzatma ve servo kabloları ile uçuş kontrol kartı bağlantıları da denetlenir.","o":[["Kontroller yapılırken pervane takılı değildir, uçuşa gitmeden hemen önce takılır; motor aparatı, kanat bağlantısı, servo/yeke/stoper, kontrol yüzeyleri ve içerideki bileşenlerin sabitliği kontrol edilir",true],["Pervane en başta takılır ve bir daha çıkarılmaz",false],["Yalnızca kanat kontrol edilir",false],["Mekanik kontrol uçuştan sonra yapılır",false]]},{"m":"Videodaki sistemde batarya bağlanınca motorlar kapalıysa araç nasıl aktif edilir?","a":"Aynı güvenlik durumunu kapatmak için gaz en aşağı ve tam sol rudder kullanılır.","o":[["Kumandadan gaz en aşağı ve tam sağ rudder verilir",true],["Gaz tam yukarı ve tam sol rudder verilir",false],["Batarya çıkarılıp tekrar takılır",false],["Yalnızca arayüzdeki butona basılır",false]]},{"m":"Tam gaz testinin amacı videoda nedir?","a":"Test hem uçuş öncesinde hem de pistte uçuşa başlamadan hemen önce yapılır.","o":[["Batarya zayıfsa motorun tam gazda yeterli performans veremediğini uçuştan önce fark edip uçuşu iptal edebilmek",true],["Motoru ısıtmak",false],["Pervaneyi balanslamak",false],["GPS'i hızlandırmak",false]]},{"m":"Kontrol listesine uçuşun amacını yazmak neden önemlidir?","a":"Listenin köşesinde saat, rüzgar kuvveti, hava durumu ve uçuş numarası gibi bilgiler de yer alır.","o":[["Sonradan hangi amaçlarla uçulduğuna, başarı ve hata türlerine ve çözümlere geri dönüp bakabilmek için",true],["Uçuş izni almak için",false],["Pil ömrünü uzatmak için",false],["Sigorta için",false]]},{"m":"Videoya göre kalkış, iniş ve uçuş sırası nasıl olmalıdır?","a":"Rüzgar yönü bayrak veya ağaçlara bakılarak belirlenir; kalkış elle atılarak yapılır.","o":[["Rüzgara karşı kalkış ve iniş; önce araç tanınsın diye denge (manuel destekli) uçuşu, sonra otonom uçuş",true],["Rüzgarı arkaya alarak kalkış; ilk uçuşta otonom",false],["Yönün önemi yoktur",false],["Önce tam otonom, sonra manuel",false]]},{"m":"İlk uçuşta aracı serbest bırakınca burun aşağı gidiyorsa videoda ne yapılır?","a":"Uçuş sonrası notta 'stabil ve burun yukarı trim verildi' yazılmıştır.","o":[["Kumandadan burun yukarı trim verilir",true],["Ağırlık merkezi geriye alınıp uçuş durdurulur",false],["Aracın pili değiştirilir",false],["Hiçbir şey yapılmaz",false]]},{"m":"Otonom uçuş öncesinde pusula kalibrasyonu neden zorunludur?","a":"Denge uçuşunda GPS bağlı olmadığı için pusula ayarı ilk uçuşta atlanmıştı.","o":[["Yapılmazsa araç otonom uçuşta yönünü bulamaz; araç her yöne döndürülerek kalibre edilir ve ardından arayüzde yönün doğruluğu kontrol edilir",true],["Pili şarj etmek için",false],["Motor gürültüsünü azaltmak için",false],["Yalnızca manuel uçuşta gerekir",false]]}]$json$::jsonb) loop
    if exists (select 1 from public.questions where quiz_id = v_quiz and metin = r->>'m') then continue; end if;
    v_sira := v_sira + 1;
    insert into public.questions (quiz_id, metin, sira, aciklama)
      values (v_quiz, r->>'m', v_sira, r->>'a') returning id into v_q;
    j := 0;
    for o in select * from jsonb_array_elements(r->'o') loop
      j := j + 1;
      insert into public.question_options (question_id, metin, dogru, sira)
        values (v_q, o->>0, (o->>1)::boolean, j);
    end loop;
  end loop;
end $q$;

